insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se o réu estiver preso, será pessoalmente citado, não se admitindo, nesse caso, a citação por edital ou outra forma ficta.', '["Réu preso: citação pessoal."]'::jsonb, '["Vedada a citação por edital do réu preso."]'::jsonb, 'O réu preso é citado no estabelecimento prisional.', '["Assertiva que admite a citação por edital do réu preso erra."]'::jsonb, '[]'::jsonb, '["Art. 361"]'::jsonb, 'under_review', 'claude'
