insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se o réu não for encontrado, será citado por edital, com o prazo de 15 dias.', '["Réu não encontrado: citação por edital.","Prazo de 15 dias."]'::jsonb, '["Prazo de 15 dias."]'::jsonb, 'O réu não é localizado, e o juiz determina a citação por edital.', '["Assertiva que fixa em 30 dias o prazo do edital de citação erra neste art. 361: são 15 dias."]'::jsonb, '[]'::jsonb, '["Art. 363","Art. 365"]'::jsonb, 'under_review', 'claude'
