insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Verificando que o réu se oculta para não ser citado, o oficial de justiça certificará a ocorrência e procederá à citação com hora certa, na forma estabelecida no Código de Processo Civil. Completada a citação com hora certa, se o acusado não comparecer, ser-lhe-á nomeado defensor dativo.', '["Réu que se oculta: oficial certifica e cita com hora certa.","Se o acusado não comparecer, defensor dativo."]'::jsonb, '["Citação ficta com hora certa."]'::jsonb, 'O oficial constata a ocultação do réu e o cita com hora certa.', '["Assertiva que determina a citação por edital quando o réu se oculta erra: é com hora certa."]'::jsonb, '[{"termo":"Citação com hora certa","significado":"Citação ficta feita quando o réu se oculta."}]'::jsonb, '["Art. 355"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-362'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O processo terá completada a sua formação quando realizada a citação do acusado. Não sendo encontrado o acusado, será procedida a citação por edital. Comparecendo o acusado citado por edital, em qualquer tempo, o processo observará o disposto nos arts. 394 e seguintes. Os incisos I e II foram revogados.', '["A formação do processo se completa com a citação.","Não encontrado: citação por edital.","Comparecimento do citado por edital: segue o rito dos arts. 394 e seguintes."]'::jsonb, '["Citação válida completa a relação processual."]'::jsonb, 'Citado por edital, o acusado comparece depois e o processo segue.', '["Assertiva que considera completa a relação processual antes da citação erra."]'::jsonb, '[]'::jsonb, '["Art. 361","Art. 394"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-363'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'No caso do artigo anterior, no inciso I, o prazo será fixado pelo juiz entre 15 e 90 dias, de acordo com as circunstâncias, e, no caso do inciso II, o prazo será de trinta dias.', '["Prazo do edital fixado pelo juiz entre 15 e 90 dias (inciso I).","Trinta dias (inciso II)."]'::jsonb, '["Dispositivo ligado a incisos revogados do art. 363; leitura histórica."]'::jsonb, 'Texto histórico, sem aplicação prática atual.', '["Assertiva que aplica hoje o art. 364 sem considerar a revogação dos incisos do art. 363 erra."]'::jsonb, '[]'::jsonb, '["Art. 363"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-364'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O edital de citação indicará o nome do juiz que a determinar; o nome do réu ou seus sinais característicos, residência e profissão, se constarem do processo; o fim para que é feita a citação; o juízo, o dia, a hora e o lugar em que o réu deverá comparecer; e o prazo, que será contado do dia da publicação na imprensa, se houver, ou da afixação. O edital será afixado à porta do edifício onde funcionar o juízo e publicado pela imprensa, onde houver, devendo a afixação ser certificada pelo oficial e a publicação provada por exemplar do jornal ou certidão do escrivão.', '["Nome do juiz.","Nome ou sinais, residência e profissão do réu.","Finalidade da citação.","Juízo, dia, hora e lugar.","Prazo contado da publicação ou afixação.","Afixação certificada e publicação provada."]'::jsonb, '["Prazo conta da publicação na imprensa ou da afixação."]'::jsonb, 'O edital é afixado à porta do fórum e publicado no jornal.', '["Assertiva que dispensa a afixação do edital à porta do fórum erra."]'::jsonb, '[]'::jsonb, '["Art. 361"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-365'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se o acusado, citado por edital, não comparecer, nem constituir advogado, ficarão suspensos o processo e o curso do prazo prescricional, podendo o juiz determinar a produção antecipada das provas consideradas urgentes e, se for o caso, decretar prisão preventiva, nos termos do art. 312.', '["Citado por edital, sem comparecer nem constituir advogado: suspensão do processo e da prescrição.","Possível produção antecipada de provas urgentes.","Possível prisão preventiva, nos termos do art. 312."]'::jsonb, '["Suspensão do processo E da prescrição.","Súmula 415 do STJ: o período de suspensão da prescrição é regulado pelo máximo da pena cominada."]'::jsonb, 'Réu citado por edital não comparece: o processo e a prescrição ficam suspensos.', '["Assertiva que suspende apenas o processo, sem suspender a prescrição, no art. 366 erra."]'::jsonb, '[]'::jsonb, '["Art. 361","Art. 367"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-366'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O processo seguirá sem a presença do acusado que, citado ou intimado pessoalmente para qualquer ato, deixar de comparecer sem motivo justificado, ou, no caso de mudança de residência, não comunicar o novo endereço ao juízo.', '["Acusado citado ou intimado pessoalmente que falta sem justificativa: o processo segue sem ele.","Mudança de endereço não comunicada: mesmo efeito."]'::jsonb, '["Revelia: citação pessoal + ausência injustificada."]'::jsonb, 'Réu citado pessoalmente não comparece e o processo prossegue sem ele.', '["Assertiva que suspende o processo na revelia do réu citado pessoalmente erra: o processo segue."]'::jsonb, '[{"termo":"Revelia","significado":"Ausência injustificada do acusado citado pessoalmente."}]'::jsonb, '["Art. 366"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-367'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Estando o acusado no estrangeiro, em lugar sabido, será citado mediante carta rogatória, suspendendo-se o curso do prazo de prescrição até o seu cumprimento.', '["Acusado no exterior em lugar sabido: citação por carta rogatória.","Suspensão do prazo prescricional até o cumprimento."]'::jsonb, '["Suspende a prescrição."]'::jsonb, 'Réu residente em outro país é citado por carta rogatória.', '["Assertiva que cita por edital o acusado no exterior em lugar sabido erra: é por carta rogatória."]'::jsonb, '[]'::jsonb, '["Art. 369"]'::jsonb, 'under_review', 'claude'
