select u.id, u.content_sha256, 'Será admissível a intimação por despacho na petição em que for requerida, observado o disposto no art. 357.', '["Intimação por despacho na própria petição que a requer, observado o art. 357."]'::jsonb, '["Observar as formalidades do art. 357."]'::jsonb, 'O juiz despacha na petição e determina a intimação do interessado.', '["Assertiva que veda a intimação por despacho na petição erra."]'::jsonb, '[]'::jsonb, '["Art. 357"]'::jsonb, 'under_review', 'claude'
