insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Adiada, por qualquer motivo, a instrução criminal, o juiz marcará desde logo, na presença das partes e testemunhas, dia e hora para seu prosseguimento, do que se lavrará termo nos autos.', '["Instrução adiada: o juiz marca desde logo novo dia e hora.","Presença das partes e testemunhas.","Termo nos autos."]'::jsonb, '["Evita nova intimação: todos saem intimados."]'::jsonb, 'A audiência é adiada, e o juiz já marca nova data na presença de todos.', '["Assertiva que exige nova intimação das partes após o adiamento marcado na presença delas erra."]'::jsonb, '[]'::jsonb, '["Art. 370"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-372'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A aplicação provisória de interdições de direitos poderá ser determinada pelo juiz, de ofício ou a requerimento do Ministério Público, do querelante, do assistente, do ofendido ou de seu representante legal, ainda que este não se tenha constituído assistente: durante a instrução criminal após a apresentação da defesa ou do prazo concedido; na sentença de pronúncia; na decisão confirmatória da pronúncia ou na que, em grau de recurso, pronunciar o réu; e na sentença condenatória recorrível. No primeiro caso, havendo requerimento, o réu ou seu defensor será ouvido no prazo de 2 dias. Decretada a medida, serão feitas as comunicações para a sua execução.', '["Aplicação provisória de interdições de direitos pelo juiz, de ofício ou a requerimento.","Momentos: instrução (após a defesa), pronúncia, confirmação da pronúncia e sentença condenatória recorrível.","Instrução: defesa ouvida em 2 dias."]'::jsonb, '["Quatro momentos."]'::jsonb, 'Na sentença condenatória recorrível, o juiz aplica provisoriamente a interdição de direitos.', '["Assertiva que permite a aplicação provisória de interdição antes da apresentação da defesa erra."]'::jsonb, '[]'::jsonb, '["Art. 374"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-373'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Não caberá recurso do despacho ou da parte da sentença que decretar ou denegar a aplicação provisória de interdições de direitos, mas estas poderão ser substituídas ou revogadas: se aplicadas no curso da instrução criminal, durante esta ou pelas sentenças a que se referem os incisos II, III e IV do artigo anterior; se aplicadas na sentença de pronúncia, pela decisão que, em grau de recurso, a confirmar, total ou parcialmente, ou pela sentença condenatória recorrível; e se aplicadas na decisão a que se refere o inciso III do artigo anterior, pela sentença condenatória recorrível.', '["Decisão sobre aplicação provisória de interdição: sem recurso.","Pode ser substituída ou revogada em momentos posteriores."]'::jsonb, '["Sem recurso, mas com possibilidade de revogação ou substituição."]'::jsonb, 'A interdição aplicada na pronúncia é revogada na sentença condenatória recorrível.', '["Assertiva que prevê recurso em sentido estrito contra a decisão sobre interdição provisória erra."]'::jsonb, '[]'::jsonb, '["Art. 373"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-374'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
