insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Transitando em julgado a sentença, observar-se-á, quanto à execução das medidas de segurança definitivamente aplicadas, o disposto no Título V do Livro IV.', '["Execução das medidas de segurança definitivas segue o Título V do Livro IV."]'::jsonb, '["Remissão ao Livro da execução."]'::jsonb, 'Após o trânsito, a medida de segurança é executada conforme o Título V do Livro IV.', '["Assertiva que aplica regras próprias do Livro I à execução das medidas definitivas erra."]'::jsonb, '[]'::jsonb, '["Art. 378"]'::jsonb, 'under_review', 'claude'
