select u.id, u.content_sha256, 'A aplicação provisória de medida de segurança obstará a concessão de fiança e tornará sem efeito a anteriormente concedida.', '["Medida de segurança provisória impede fiança.","Torna sem efeito a fiança anterior."]'::jsonb, '["Incompatibilidade com a fiança."]'::jsonb, 'Com a medida de segurança provisória, a fiança anterior perde o efeito.', '["Assertiva que admite fiança cumulada com medida de segurança provisória erra."]'::jsonb, '[]'::jsonb, '["Art. 378"]'::jsonb, 'under_review', 'claude'
