insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A sentença conterá os nomes das partes ou as indicações necessárias para identificá-las; a exposição sucinta da acusação e da defesa; a indicação dos motivos de fato e de direito em que se fundar a decisão; a indicação dos artigos de lei aplicados; o dispositivo; e a data e a assinatura do juiz.', '["I: partes.","II: relatório (exposição sucinta da acusação e da defesa).","III: fundamentação (motivos de fato e de direito).","IV: artigos de lei aplicados.","V: dispositivo.","VI: data e assinatura do juiz."]'::jsonb, '["Estrutura: relatório, fundamentação e dispositivo."]'::jsonb, 'A sentença traz relatório, fundamentação, dispositivo, data e assinatura.', '["Assertiva que dispensa a fundamentação de fato e de direito na sentença erra."]'::jsonb, '[]'::jsonb, '["Art. 387"]'::jsonb, 'under_review', 'claude'
