insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Não apresentada a resposta no prazo legal, o juiz nomeará defensor para oferecê-la em até 10 dias, concedendo-lhe vista dos autos.', '["Sem resposta no prazo: juiz nomeia defensor.","Defensor oferece a resposta em até 10 dias, com vista dos autos."]'::jsonb, '["Mesmo prazo de 10 dias."]'::jsonb, 'O acusado não responde, e o juiz nomeia defensor para oferecer a resposta.', '["Assertiva que dispensa a nomeação de defensor se não houver resposta erra."]'::jsonb, '[]'::jsonb, '["Art. 396-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-408'
