insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Apresentada a defesa, o juiz ouvirá o Ministério Público ou o querelante sobre preliminares e documentos, em 5 dias.', '["Juiz ouve o MP ou o querelante sobre preliminares e documentos.","Prazo de 5 dias."]'::jsonb, '["Contraditório sobre as preliminares da defesa."]'::jsonb, 'A defesa apresenta preliminares, e o MP se manifesta em 5 dias.', '["Assertiva que fixa em 10 dias a manifestação do MP sobre as preliminares erra: são 5 dias."]'::jsonb, '[]'::jsonb, '["Art. 410"]'::jsonb, 'under_review', 'claude'
