insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O juiz determinará a inquirição das testemunhas e a realização das diligências requeridas pelas partes, no prazo máximo de 10 dias.', '["Inquirição de testemunhas e diligências em até 10 dias."]'::jsonb, '["Prazo de 10 dias para a determinação."]'::jsonb, 'Em até 10 dias, o juiz determina a inquirição das testemunhas.', '["Assertiva que fixa em 30 dias esse prazo erra: são 10 dias."]'::jsonb, '[]'::jsonb, '["Art. 409","Art. 411"]'::jsonb, 'under_review', 'claude'
