insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A intimação da decisão de pronúncia será feita pessoalmente ao acusado, ao defensor nomeado e ao Ministério Público; ao defensor constituído, ao querelante e ao assistente do MP, na forma do §1º do art. 370. Será intimado por edital o acusado solto que não for encontrado.', '["Intimação pessoal: acusado, defensor nomeado e MP.","Defensor constituído, querelante e assistente: por publicação (art. 370, §1º).","Acusado solto não encontrado: edital."]'::jsonb, '["Edital só para acusado SOLTO."]'::jsonb, 'O acusado preso é intimado pessoalmente da pronúncia.', '["Assertiva que admite a intimação por edital do acusado preso, da pronúncia, erra."]'::jsonb, '[]'::jsonb, '["Art. 370"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-420'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Preclusa a decisão de pronúncia, os autos serão encaminhados ao juiz presidente do Tribunal do Júri. Ainda que preclusa a pronúncia, havendo circunstância superveniente que altere a classificação do crime, o juiz ordenará a remessa dos autos ao Ministério Público. Em seguida, os autos serão conclusos ao juiz para decisão.', '["Preclusa a pronúncia: autos ao juiz presidente do Júri.","Circunstância superveniente que altera a classificação: remessa ao MP.","Depois, autos conclusos ao juiz."]'::jsonb, '["Remessa ao MP em caso de circunstância superveniente."]'::jsonb, 'A vítima morre depois da pronúncia, mudando a classificação do crime, e os autos vão ao MP.', '["Assertiva que impede qualquer alteração da classificação após a preclusão da pronúncia erra."]'::jsonb, '[]'::jsonb, '["Art. 413","Art. 422"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-421'
